solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

namespace
{
    const char* alphabet(bool url)
    {
        return url ? "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
                   : "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    }

    int valueOf(char c, bool url)
    {
        if (c >= 'A' && c <= 'Z') return c - 'A';
        if (c >= 'a' && c <= 'z') return c - 'a' + 26;
        if (c >= '0' && c <= '9') return c - '0' + 52;
        if (c == (url ? '-' : '+')) return 62;
        if (c == (url ? '_' : '/')) return 63;
        return -1;
    }
}

std::string base64Encode(const std::vector<std::uint8_t>& data, bool url = false)
{
    const char* abc{ alphabet(url) };
    std::string out;
    std::size_t i{ 0 };
    for (; i + 3 <= data.size(); i += 3)
    {
        const std::uint32_t n{ (std::uint32_t{ data[i] } << 16) | (std::uint32_t{ data[i + 1] } << 8) | data[i + 2] };
        out += abc[(n >> 18) & 63];
        out += abc[(n >> 12) & 63];
        out += abc[(n >> 6) & 63];
        out += abc[n & 63];
    }
    const std::size_t left{ data.size() - i };
    if (left == 1)
    {
        const std::uint32_t n{ std::uint32_t{ data[i] } << 16 };
        out += abc[(n >> 18) & 63];
        out += abc[(n >> 12) & 63];
        if (!url) out += "==";
    }
    else if (left == 2)
    {
        const std::uint32_t n{ (std::uint32_t{ data[i] } << 16) | (std::uint32_t{ data[i + 1] } << 8) };
        out += abc[(n >> 18) & 63];
        out += abc[(n >> 12) & 63];
        out += abc[(n >> 6) & 63];
        if (!url) out += '=';
    }
    return out;
}

std::optional<std::vector<std::uint8_t>> base64Decode(std::string_view text, bool url = false)
{
    if (!url)
    {
        if (text.size() % 4 != 0) return std::nullopt;
        int pads{ 0 };
        while (pads < 2 && !text.empty() && text.back() == '=')
        {
            text.remove_suffix(1);
            ++pads;
        }
    }
    if (text.find('=') != std::string_view::npos) return std::nullopt;
    if (text.size() % 4 == 1) return std::nullopt;

    std::vector<int> values;
    for (char c : text)
    {
        const int v{ valueOf(c, url) };
        if (v < 0) return std::nullopt;
        values.push_back(v);
    }
    std::vector<std::uint8_t> out;
    std::size_t i{ 0 };
    for (; i + 4 <= values.size(); i += 4)
    {
        const std::uint32_t n{ (std::uint32_t(values[i]) << 18) | (std::uint32_t(values[i + 1]) << 12) | (std::uint32_t(values[i + 2]) << 6) | std::uint32_t(values[i + 3]) };
        out.push_back(static_cast<std::uint8_t>(n >> 16));
        out.push_back(static_cast<std::uint8_t>(n >> 8));
        out.push_back(static_cast<std::uint8_t>(n));
    }
    const std::size_t left{ values.size() - i };
    if (left == 2)
    {
        if ((values[i + 1] & 0x0F) != 0) return std::nullopt;
        out.push_back(static_cast<std::uint8_t>((values[i] << 2) | (values[i + 1] >> 4)));
    }
    else if (left == 3)
    {
        if ((values[i + 2] & 0x03) != 0) return std::nullopt;
        out.push_back(static_cast<std::uint8_t>((values[i] << 2) | (values[i + 1] >> 4)));
        out.push_back(static_cast<std::uint8_t>(((values[i + 1] & 0x0F) << 4) | (values[i + 2] >> 2)));
    }
    return out;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
Bytes bytes(std::string_view s) { return Bytes(s.begin(), s.end()); }
TEST("the RFC's test vectors") {
    CHECK_EQ(base64Encode(bytes("")), std::string(""));
    CHECK_EQ(base64Encode(bytes("f")), std::string("Zg=="));
    CHECK_EQ(base64Encode(bytes("fo")), std::string("Zm8="));
    CHECK_EQ(base64Encode(bytes("foo")), std::string("Zm9v"));
    CHECK_EQ(base64Encode(bytes("foob")), std::string("Zm9vYg=="));
    CHECK_EQ(base64Encode(bytes("fooba")), std::string("Zm9vYmE="));
    CHECK_EQ(base64Encode(bytes("foobar")), std::string("Zm9vYmFy"));
}
TEST("decoding the vectors back") {
    for (std::string_view s : { "", "f", "fo", "foo", "foob", "fooba", "foobar" }) {
        const auto d{ base64Decode(base64Encode(bytes(s))) };
        CHECK(d.has_value() && *d == bytes(s));
    }
}
TEST("the URL-safe variant") {
    CHECK_EQ(base64Encode({ 0xFB, 0xFF }), std::string("+/8="));
    CHECK_EQ(base64Encode({ 0xFB, 0xFF }, true), std::string("-_8"));
    CHECK_EQ(base64Encode(bytes("foob"), true), std::string("Zm9vYg"));
    const auto d{ base64Decode("-_8", true) };
    CHECK(d.has_value() && *d == (Bytes{ 0xFB, 0xFF }));
    const auto e{ base64Decode("Zm9vYg", true) };
    CHECK(e.has_value() && *e == bytes("foob"));
    CHECK(!base64Decode("+/8=", true).has_value());
    CHECK(!base64Decode("-_8=").has_value());
}
TEST("every byte value") {
    Bytes all(256);
    for (int i{ 0 }; i < 256; ++i) all[i] = static_cast<std::uint8_t>(i);
    for (bool url : { false, true }) {
        const auto d{ base64Decode(base64Encode(all, url), url) };
        CHECK(d.has_value() && *d == all);
    }
}
TEST("rejecting what encoding could not produce") {
    CHECK(!base64Decode("Zm9").has_value());
    CHECK(!base64Decode("Zm9v=").has_value());
    CHECK(!base64Decode("Zm=v").has_value());
    CHECK(!base64Decode("Z===").has_value());
    CHECK(!base64Decode("====").has_value());
    CHECK(!base64Decode("Zm 9v").has_value());
    CHECK(!base64Decode("Zm9v\n").has_value());
    CHECK(!base64Decode("Zm9*").has_value());
    CHECK(!base64Decode("Zh==").has_value());
    CHECK(!base64Decode("Zm9=").has_value());
    CHECK(!base64Decode("Zm9vY", true).has_value());
    CHECK(!base64Decode("Zh", true).has_value());
    CHECK(base64Decode("Zg", true).has_value());
    const auto empty{ base64Decode("") };
    CHECK(empty.has_value() && empty->empty());
}

